const MIN = 60000;
const HOUR = 3600000;
const DAY = 86400000;

const DEFAULT_SETTINGS = {
  clinicName: 'Willow Creek Dental',
  shortName: 'Willow Creek Dental',
  clinicPhone: '+15125550142',
  frontDeskName: 'Maria',
  frontDeskPhone: '+15125550143',
  frontDeskEmail: 'frontdesk@example.com',
  address: '2140 Willow Creek Dr, Austin',
  timezone: 'America/Chicago',
  openHour: 8,
  closeHour: 17,
  lunchHour: 12,
  reminderFirst: 72,
  reminderSecond: 24,
  reminderFinal: 2,
  offerBatch: 3,
  offerMinutes: 20,
  minNoticeHours: 2,
  riskCallList: 60,
  quietStart: 20,
  quietEnd: 8,
  autoFill: true,
  minimumNecessary: true,
  aiEnabled: true,
  demoMode: true,
  claudeModel: 'claude-opus-5',
  baselineNoShowRate: 0.17,
  insurers: 'Delta Dental, Cigna, Aetna, MetLife, Guardian, United Concordia',
  parking: 'Free parking right outside, with two accessible spots by the door.',
  templateFirst: 'Hi {first}, it’s {clinic}. You’re booked {when} with {provider}. Reply C to confirm or R to reschedule.',
  templateSecond: 'Hi {first}, see you {when} with {provider} at {clinic}. Reply C to confirm, or R if you need a different time.',
  templateFinal: 'See you at {time} today, {first}. We’re at {address}. Reply L if you’re running late.',
  templateOffer: 'Hi {first}, {clinic} here. A spot just opened {when} with {provider}. Want it? Reply YES to book. The first reply gets it.',
  providers: [
    { key: 'patel', name: 'Dr. Anika Patel', short: 'Dr. Patel', role: 'dentist' },
    { key: 'okafor', name: 'Dr. James Okafor', short: 'Dr. Okafor', role: 'dentist' },
    { key: 'reyes', name: 'Lena Reyes, RDH', short: 'Lena', role: 'hygienist' }
  ],
  types: [
    { key: 'cleaning', name: 'Cleaning and checkup', minutes: 60, value: 185, role: 'hygienist' },
    { key: 'exam', name: 'New patient exam', minutes: 60, value: 260, role: 'dentist' },
    { key: 'filling', name: 'Filling', minutes: 60, value: 320, role: 'dentist' },
    { key: 'crown', name: 'Crown', minutes: 90, value: 1150, role: 'dentist' },
    { key: 'rootcanal', name: 'Root canal', minutes: 90, value: 1080, role: 'dentist' },
    { key: 'whitening', name: 'Whitening', minutes: 60, value: 450, role: 'dentist' },
    { key: 'emergency', name: 'Emergency visit', minutes: 30, value: 220, role: 'dentist' }
  ]
};

let ZONE = null;
const FMT = {};
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

const setZone = z => {
  ZONE = z || null;
};

const zoned = o => (ZONE ? { ...o, timeZone: ZONE } : o);

function parts(t) {
  const d = new Date(t);
  if (!ZONE) return { y: d.getFullYear(), mo: d.getMonth(), d: d.getDate(), h: d.getHours(), mi: d.getMinutes(), wd: d.getDay() };
  const f = FMT[ZONE] || (FMT[ZONE] = new Intl.DateTimeFormat('en-US', { timeZone: ZONE, year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', weekday: 'short', hourCycle: 'h23' }));
  const o = {};
  for (const p of f.formatToParts(d)) o[p.type] = p.value;
  return { y: +o.year, mo: +o.month - 1, d: +o.day, h: +o.hour % 24, mi: +o.minute, wd: WD.indexOf(o.weekday) };
}

function make(y, mo, d, h = 0, mi = 0) {
  if (!ZONE) return new Date(y, mo, d, h, mi, 0, 0).getTime();
  const want = Date.UTC(y, mo, d, h, mi);
  let guess = want;
  for (let i = 0; i < 3; i++) {
    const p = parts(guess);
    guess -= Date.UTC(p.y, p.mo, p.d, p.h, p.mi) - want;
  }
  return guess;
}

const hourOf = t => parts(t).h;
const weekdayOf = t => parts(t).wd;

const dayStart = t => {
  const p = parts(t);
  return make(p.y, p.mo, p.d);
};

const addDays = (t, n) => {
  const p = parts(t);
  return make(p.y, p.mo, p.d + n, p.h, p.mi);
};

const atTime = (day, h, m = 0) => {
  const p = parts(day);
  return make(p.y, p.mo, p.d, h, m);
};

const isWorkday = t => {
  const w = weekdayOf(t);
  return w >= 1 && w <= 5;
};

const nextWorkday = (t, after = 1) => {
  let d = dayStart(t);
  let n = 0;
  while (n < after) {
    d = addDays(d, 1);
    if (isWorkday(d)) n += 1;
  }
  return d;
};

const timeLabel = t => new Date(t).toLocaleTimeString('en-US', zoned({ hour: 'numeric', minute: '2-digit' }));

function dayLabel(t, now = Date.now()) {
  const d = dayStart(t);
  const today = dayStart(now);
  if (d === today) return 'today';
  if (d === addDays(today, 1)) return 'tomorrow';
  return new Date(t).toLocaleDateString('en-US', zoned({ weekday: 'short', month: 'short', day: 'numeric' }));
}

function whenLabel(t, now = Date.now()) {
  const day = dayLabel(t, now);
  if (day === 'today' || day === 'tomorrow') {
    const wd = new Date(t).toLocaleDateString('en-US', zoned({ weekday: 'short', month: 'short', day: 'numeric' }));
    return day + ', ' + wd + ' at ' + timeLabel(t);
  }
  return day + ' at ' + timeLabel(t);
}

const providerOf = (s, key) => s.providers.find(p => p.key === key) || s.providers[0];
const typeOf = (s, key) => s.types.find(t => t.key === key) || s.types[0];
const NL = String.fromCharCode(10);
const WS = new RegExp('[' + String.fromCharCode(32, 9, 10, 13, 160) + ']+', 'g');

const firstName = name => String(name || '').trim().split(WS)[0] || 'there';

function fill(template, vars) {
  return String(template || '').replace(/[{]([a-zA-Z0-9_]+)[}]/g, (m, k) => (vars[k] != null ? vars[k] : m));
}

function textVars(s, appt, patient, now) {
  return {
    first: firstName(patient.name),
    clinic: s.shortName,
    when: whenLabel(appt.start, now),
    time: timeLabel(appt.start),
    provider: providerOf(s, appt.provider).short,
    address: s.address,
    type: s.minimumNecessary ? 'your appointment' : typeOf(s, appt.type).name.toLowerCase()
  };
}

const ACTIVE = ['booked', 'confirmed'];
const occupies = a => ACTIVE.includes(a.status) || a.status === 'completed' || a.status === 'no_show' || a.status === 'arrived';

function riskOf(appt, patient, now, s = DEFAULT_SETTINGS) {
  const f = [];
  const add = (key, label, points) => f.push({ key, label, points });
  const start = Date.parse(appt.start);
  if (patient.noShows) add('history', patient.noShows === 1 ? 'Missed a visit before' : 'Missed ' + patient.noShows + ' visits before', Math.min(40, 21 * patient.noShows));
  if (patient.lateCancels) add('cancels', patient.lateCancels === 1 ? 'One late cancellation' : patient.lateCancels + ' late cancellations', Math.min(16, 8 * patient.lateCancels));
  const lead = (start - Date.parse(appt.bookedAt)) / DAY;
  if (lead >= 28) add('lead', 'Booked ' + Math.round(lead / 7) + ' weeks ago', 14);
  else if (lead >= 14) add('lead', 'Booked ' + Math.round(lead / 7) + ' weeks ago', 8);
  if (!patient.visits) add('new', 'First visit', 10);
  const pp = parts(start);
  const wd = pp.wd;
  const h = pp.h;
  if (wd === 1 && h < 11) add('slot', 'Monday morning slot', 6);
  else if (wd === 5 && h >= 13) add('slot', 'Friday afternoon slot', 6);
  else if (h === s.openHour) add('slot', 'First slot of the day', 4);
  const r = appt.reminders || {};
  const lastReminder = r.second || r.first;
  if (lastReminder && !appt.confirmedAt && now - Date.parse(lastReminder) > 3 * HOUR) add('silent', 'No reply to the reminder', 22);
  if (appt.confirmedAt) add('confirmed', appt.confirmedBy === 'call' ? 'Confirmed on a call' : appt.confirmedBy === 'move' ? 'Picked this time by text' : 'Confirmed by text', -46);
  if (patient.visits >= 6 && !patient.noShows) add('loyal', 'Reliable regular', -12);
  const score = Math.max(2, Math.min(97, 14 + f.reduce((a, b) => a + b.points, 0)));
  return { score, level: score >= s.riskCallList ? 'high' : score >= 35 ? 'medium' : 'low', factors: f.sort((a, b) => b.points - a.points) };
}

function canDo(s, providerKey, typeKey) {
  return providerOf(s, providerKey).role === typeOf(s, typeKey).role;
}

function busy(appts, provider, start, minutes, ignoreId) {
  const a0 = start;
  const a1 = start + minutes * MIN;
  return appts.some(a => {
    if (a.id === ignoreId || a.provider !== provider || !occupies(a)) return false;
    const b0 = Date.parse(a.start);
    const b1 = b0 + a.minutes * MIN;
    return a0 < b1 && b0 < a1;
  });
}

function fitsHours(s, start, minutes) {
  const pp = parts(start);
  const h0 = pp.h + pp.mi / 60;
  const h1 = h0 + minutes / 60;
  if (!isWorkday(start)) return false;
  if (h0 < s.openHour || h1 > s.closeHour) return false;
  if (h0 < s.lunchHour + 1 && h1 > s.lunchHour) return false;
  return true;
}

function openSlots(state, opts) {
  const s = state.settings;
  const { minutes, providers, days, from = s.openHour, to = s.closeHour, now, limit = 3, ignoreId } = opts;
  const out = [];
  for (const day of days) {
    for (let h = s.openHour; h < s.closeHour; h += 0.5) {
      if (h < from || h >= to) continue;
      const start = atTime(day, Math.floor(h), h % 1 ? 30 : 0);
      if (start < now + s.minNoticeHours * HOUR) continue;
      if (!fitsHours(s, start, minutes)) continue;
      for (const p of providers) {
        if (busy(state.appts, p, start, minutes, ignoreId)) continue;
        out.push({ provider: p, start: new Date(start).toISOString() });
        break;
      }
    }
  }
  const picked = [];
  for (const o of out) {
    const t = Date.parse(o.start);
    if (picked.some(p => Math.abs(Date.parse(p.start) - t) < 60 * MIN)) continue;
    picked.push(o);
    if (picked.length >= limit) break;
  }
  return picked;
}

const DAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const SHORT = ['sun', 'mon', 'tue', 'wed', 'thu', 'fri', 'sat'];

function parsePref(text, now, s = DEFAULT_SETTINGS) {
  const t = ' ' + String(text || '').toLowerCase().replace(/[^a-z0-9: ]/g, ' ') + ' ';
  const today = dayStart(now);
  let days = [];
  const named = [];
  DAYS.forEach((d, i) => {
    if (t.includes(' ' + d + ' ') || t.includes(' ' + SHORT[i] + ' ') || t.includes(' ' + d + 's ')) named.push(i);
  });
  const nextWeek = /next week/.test(t);
  if (named.length) {
    for (const wd of named) {
      let d = addDays(today, 1);
      for (let k = 0; k < 7; k++) {
        if (weekdayOf(d) === wd) break;
        d = addDays(d, 1);
      }
      if (nextWeek && d < addDays(today, 7 - weekdayOf(today) + 1)) d = addDays(d, 7);
      days.push(d);
    }
  } else if (/ tomorrow /.test(t)) {
    days.push(addDays(today, 1));
  } else if (/ today | this afternoon | this morning /.test(t)) {
    days.push(today);
  } else if (nextWeek) {
    const mon = addDays(today, ((8 - weekdayOf(today)) % 7) || 7);
    for (let i = 0; i < 5; i++) days.push(addDays(mon, i));
  } else if (/this week|later this week/.test(t)) {
    for (let i = 1; i <= 5; i++) {
      const d = addDays(today, i);
      if (weekdayOf(d) === 6 || weekdayOf(d) === 0) break;
      days.push(d);
    }
  }
  days = days.filter(isWorkday).sort((a, b) => a - b);
  let from = s.openHour;
  let to = s.closeHour;
  let part = null;
  if (/morning| am |early|before lunch/.test(t)) {
    to = s.lunchHour;
    part = 'morning';
  }
  if (/afternoon| pm |after lunch/.test(t)) {
    from = s.lunchHour + 1;
    part = 'afternoon';
  }
  if (/evening|after work|after school|late in the day|end of the day/.test(t)) {
    from = 15;
    part = 'late afternoon';
  }
  const after = t.match(/after ([0-9]{1,2})(?::([0-9][0-9]))?/);
  if (after) {
    let h = Number(after[1]);
    if (h < 8) h += 12;
    from = Math.max(from, h);
    part = 'after ' + timeLabel(atTime(today, h)).replace(':00', '');
  }
  const before = t.match(/before ([0-9]{1,2})(?::([0-9][0-9]))?/);
  if (before) {
    let h = Number(before[1]);
    if (h < 8) h += 12;
    to = Math.min(to, h);
    part = 'before ' + timeLabel(atTime(today, h)).replace(':00', '');
  }
  const has = days.length > 0 || part != null;
  return { days, from, to, part, has };
}

function searchDays(pref, now, count = 6) {
  if (pref.days.length) return pref.days;
  const out = [];
  let d = dayStart(now);
  if (hourOf(now) < 15) out.push(d);
  while (out.length < count) {
    d = addDays(d, 1);
    if (isWorkday(d)) out.push(d);
  }
  return out.filter(isWorkday);
}

const has = (t, re) => re.test(t);

function classify(text) {
  const t = ' ' + String(text || '').toLowerCase().replace(/[’']/g, '').replace(WS, ' ').trim() + ' ';
  const bare = t.trim().replace(/[.!]+$/, '');
  if (/^(stop|unsubscribe|stopall|end|quit)$/.test(bare)) return 'stop';
  if (/^(start|unstop)$/.test(bare)) return 'start';
  if (has(t, /chest pain|cant breathe|can not breathe|cannot breathe|trouble breathing|difficulty breathing|swallow/)) return 'clinical';
  if (has(t, /pain|hurts|hurting|ache|aching|swell|swollen|bleed|blood|fever|infect|abscess|pus|antibiotic|medication|medicine|allerg|numb|throb|broke|broken|cracked|chipped|knocked out|sensitive|is (that|this|it) normal|should i (be|take|worry)/)) return 'clinical';
  if (has(t, /running late|be late|im late|10 min|15 min|5 min|few min|stuck in traffic|on my way|be there in|running behind/) || bare === 'l') return 'late';
  if (has(t, /call me|give me a call|phone me|speak to (someone|a person|a human)|talk to (someone|a person|a human)|real person|bill|billing|invoice|payment plan|refund/)) return 'callback';
  if (/^(r|reschedule)$/.test(bare)) return 'reschedule';
  if (/^(x|cancel)$/.test(bare)) return 'cancel';
  const resched = has(t, /reschedul|move (it|my|the)|change (it|my|the)|another (day|time)|different (day|time)|other (day|time)|cant make|cannot make|can not make|wont make|wont be able|any (other )?(time|slot|chance)|anything (on|for|next|later|earlier)|can we do|could we do|push (it|back)|instead|earlier|later (time|in the)|swap|switch/);
  const cancel = has(t, /cancel|not coming|cant come|cannot come|wont be coming|call it off|no longer need|dont need/);
  if (cancel && !resched) return 'cancel';
  if (resched) return 'reschedule';
  if (/^(c|y|yes|yep|yeah|yup|ok|okay|confirm|confirmed|sure|k|👍)$/.test(bare)) return 'confirm';
  if (has(t, / confirm|see you|ill be there|i will be there|will be there|sounds good|perfect|works for me|all good|yes please| yes /)) return 'confirm';
  if (/^(no|n|nope|no thanks|pass)$/.test(bare) || has(t, /no thank|not this time|cant take it|ill pass/)) return 'decline';
  if (has(t, /park|insur|accept|in network|delta|cigna|aetna|metlife|guardian|concordia|bring|how long|address|where are you|location|directions|cost|price|how much|kids|child|x-ray|xray|wheelchair|accessib/)) return 'question';
  if (has(t, /thank|thanks|thx|great|cool|awesome|appreciate/)) return 'thanks';
  return 'other';
}

function pickOption(text, options) {
  const t = ' ' + String(text || '').toLowerCase() + ' ';
  if (/(?<![a-z0-9])(1|one|first)(?![a-z0-9])|1st|^ *a *$/.test(t)) return 0;
  if (/(?<![a-z0-9])(2|two|second)(?![a-z0-9])|2nd/.test(t) && options.length > 1) return 1;
  if (/(?<![a-z0-9])(3|three|third|last)(?![a-z0-9])|3rd/.test(t) && options.length > 2) return 2;
  const tm = t.match(/([0-9]{1,2})(?::([0-9][0-9]))? *(am|pm)?/);
  if (tm) {
    let h = Number(tm[1]);
    const m = Number(tm[2] || 0);
    if (tm[3] === 'pm' && h < 12) h += 12;
    if (!tm[3] && h < 8) h += 12;
    const i = options.findIndex(o => {
      const pp = parts(o.start);
      return pp.h === h && pp.mi === m;
    });
    if (i >= 0) return i;
  }
  for (let i = 0; i < options.length; i++) {
    const wd = DAYS[weekdayOf(options[i].start)];
    if (t.includes(wd) || t.includes(' ' + wd.slice(0, 3) + ' ')) {
      const same = options.filter(o => DAYS[weekdayOf(o.start)] === wd);
      if (same.length === 1) return i;
    }
  }
  if (/works|good|perfect|great|take it|book it|that one|fine/.test(t) && options.length === 1) return 0;
  return -1;
}

function faq(text, s, appt) {
  const t = String(text || '').toLowerCase();
  const out = [];
  if (/park/.test(t)) out.push(s.parking);
  if (/insur|accept|in network|delta|cigna|aetna|metlife|guardian|concordia/.test(t)) {
    const list = s.insurers.split(',').map(x => x.trim()).filter(Boolean);
    const named = list.find(n => t.includes(n.toLowerCase().split(' ')[0]));
    out.push(named ? 'Yes, we’re in network with ' + named + '. Bring your card and we’ll handle the claim.' : 'We’re in network with ' + list.slice(0, 4).join(', ') + ' and more. The front desk can check your plan before the visit.');
  }
  if (/bring/.test(t)) out.push('Just bring a photo ID, your insurance card and a list of any medicines you take.');
  if (/how long/.test(t) && appt) out.push('Plan for about ' + appt.minutes + ' minutes.');
  if (/address|where are you|location|directions/.test(t)) out.push('We’re at ' + s.address + '.');
  if (/cost|price|how much/.test(t)) out.push('Costs depend on your plan, so the front desk will go through them with you before any treatment starts.');
  if (/kids|child/.test(t)) out.push('Yes, we see children from age 3.');
  if (/x-ray|xray/.test(t)) out.push('If x-rays are due, they take about 10 minutes and are covered by most plans.');
  if (/wheelchair|accessib/.test(t)) out.push('Yes, the clinic is step-free with an accessible restroom.');
  return out.join(' ');
}

const INTENT = {
  confirm: { label: 'Confirmed', tone: 'good' },
  reschedule: { label: 'Rescheduled', tone: 'blue' },
  cancel: { label: 'Cancelled', tone: 'amber' },
  question: { label: 'Asked a question', tone: 'violet' },
  clinical: { label: 'Clinical concern', tone: 'red' },
  late: { label: 'Running late', tone: 'cyan' },
  callback: { label: 'Wants a call', tone: 'pink' },
  accept: { label: 'Took an open spot', tone: 'good' },
  decline: { label: 'Said no', tone: 'quiet' },
  taken: { label: 'Offer already taken', tone: 'quiet' },
  stop: { label: 'Opted out', tone: 'quiet' },
  other: { label: 'Other', tone: 'quiet' }
};

function phoneLabel(p) {
  const d = String(p || '').replace(/[^0-9]/g, '').replace(/^1(?=[0-9]{10}$)/, '');
  if (d.length !== 10) return p || '';
  return '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6);
}


const iso = t => new Date(t).toISOString();

function emptyState(settings = DEFAULT_SETTINGS) {
  return { settings: { ...settings }, patients: [], appts: [], waitlist: [], offers: [], messages: [], queue: [], seq: 0 };
}

const uid = (s, p) => p + (++s.seq).toString(36);

function addMessage(s, m) {
  const msg = { id: uid(s, 'm'), apptId: null, offerId: null, intent: null, ...m };
  s.messages.push(msg);
  return msg;
}

function note(s, patientId, body, at, extra = {}) {
  return addMessage(s, { patientId, dir: 'note', author: 'system', body, at: iso(at), ...extra });
}

const patientById = (s, id) => s.patients.find(p => p.id === id);
const apptById = (s, id) => s.appts.find(a => a.id === id);

function nextAppt(s, p, now) {
  return s.appts
    .filter(a => a.patientId === p.id && ACTIVE.includes(a.status) && Date.parse(a.start) + a.minutes * MIN > now)
    .sort((a, b) => Date.parse(a.start) - Date.parse(b.start))[0] || null;
}

function openOfferFor(s, p, now) {
  const list = s.offers
    .filter(o => o.candidates.some(c => c.patientId === p.id && !c.reply) && Date.parse(o.sentAt) <= now + 5000 && now - Date.parse(o.sentAt) < 6 * HOUR)
    .sort((a, b) => Date.parse(b.sentAt) - Date.parse(a.sentAt));
  return list[0] || null;
}

function sendReminder(s, appt, kind, now, author = 'ai') {
  const p = patientById(s, appt.patientId);
  if (!p || p.optedOut) return null;
  const S = s.settings;
  const tpl = kind === 'first' ? S.templateFirst : kind === 'final' ? S.templateFinal : S.templateSecond;
  appt.reminders = { ...(appt.reminders || {}), [kind]: iso(now) };
  return addMessage(s, { patientId: p.id, apptId: appt.id, dir: 'out', author, kind: 'reminder', body: fill(tpl, textVars(S, appt, p, now)), at: iso(now) });
}

function flag(s, p, kind, now, text) {
  p.flag = { kind, at: iso(now), text, ack: false };
}

function newPatient(s, phone, now, name = null) {
  const p = { id: uid(s, 'p'), name, phone, since: iso(now), visits: 0, noShows: 0, lateCancels: 0, optedOut: false, aiPaused: false, flag: null, pending: null, lastReplyAt: null, unread: false };
  s.patients.push(p);
  return p;
}

function inbound(s, phone, body, now, delays = [2300, 1700], opts = {}) {
  let p = s.patients.find(x => x.phone === phone);
  if (!p) p = newPatient(s, phone, now);
  const local = classify(body);
  const intent = ['clinical', 'stop', 'start', 'callback'].includes(local) || !opts.intent ? local : opts.intent;
  const msg = addMessage(s, { patientId: p.id, dir: 'in', author: 'patient', body, at: iso(now), intent });
  p.lastReplyAt = iso(now);
  p.unread = true;
  if (!s.settings.aiEnabled || p.aiPaused) {
    note(s, p.id, p.aiPaused ? 'AI is paused for this patient. Waiting for the front desk.' : 'AI replies are off. Waiting for the front desk.', now + 200);
    if (!p.flag || p.flag.ack) flag(s, p, 'reply', now, body);
    return { patient: p, intent, msg };
  }
  const res = respond(s, p, body, now, msg, opts);
  let t = now;
  res.replies.forEach((r, i) => {
    t += delays[Math.min(i, delays.length - 1)];
    addMessage(s, { patientId: p.id, apptId: res.apptId || null, offerId: res.offerId || null, dir: 'out', author: 'ai', kind: res.kind || 'reply', body: r, at: iso(t) });
  });
  return { patient: p, intent: res.intent, msg };
}

const optionLine = (s, o, i, now, base) => {
  const prov = providerOf(s.settings, o.provider);
  return (i + 1) + ') ' + whenLabel(o.start, now).replace(/^(today|tomorrow), /, '') + (o.provider !== base ? ' with ' + prov.short : '');
};

function findOptions(s, appt, pref, now) {
  const S = s.settings;
  const role = typeOf(S, appt.type).role;
  const providers = [appt.provider, ...S.providers.filter(x => x.role === role && x.key !== appt.provider).map(x => x.key)];
  const base = { minutes: appt.minutes, providers, now, ignoreId: appt.id };
  let opts = openSlots(s, { ...base, days: searchDays(pref, now), from: pref.from, to: pref.to });
  let widened = false;
  if (!opts.length && pref.days.length) {
    opts = openSlots(s, { ...base, days: searchDays({ days: [] }, Math.max(...pref.days)), from: pref.from, to: pref.to });
    widened = true;
  }
  if (!opts.length) {
    opts = openSlots(s, { ...base, days: searchDays({ days: [] }, now, 8) });
    widened = true;
  }
  return { opts, widened };
}

function respond(s, p, body, now, msg, hint = {}) {
  const S = s.settings;
  let intent = msg.intent;
  const appt = nextAppt(s, p, now);
  const offer = openOfferFor(s, p, now);
  const pend = p.pending;
  const out = [];
  const say = t => out.push(t);
  const first = firstName(p.name);
  const res = { replies: out, intent, apptId: appt ? appt.id : null };
  const mark = i => {
    intent = i;
    msg.intent = i;
    res.intent = i;
    if (appt && !appt.replyIntent) appt.replyIntent = i;
  };

  if (intent === 'stop') {
    p.optedOut = true;
    p.pending = null;
    say('You’re unsubscribed from ' + S.shortName + ' texts. Reply START to opt back in.');
    note(s, p.id, 'Opted out of texts', now + 100);
    return res;
  }
  if (intent === 'start') {
    p.optedOut = false;
    say('You’re subscribed again. We’ll text your appointment reminders.');
    return res;
  }
  if (intent === 'clinical') {
    mark('clinical');
    flag(s, p, 'clinical', now, body);
    say('I’m sorry you’re dealing with that, ' + first + '. I can’t give medical advice by text, so I’ve flagged this for our clinical team and someone will call you shortly. If it feels like an emergency, call 911 now.');
    note(s, p.id, 'Flagged for the clinical team. No advice was given by text.', now + 120, { kind: 'flag' });
    return res;
  }
  if (intent === 'callback') {
    mark('callback');
    flag(s, p, 'callback', now, body);
    say('Of course. I’ve asked the front desk to call you back. They’ll ring from ' + phoneLabel(S.clinicPhone) + ' during opening hours.');
    note(s, p.id, 'Call back requested', now + 120, { kind: 'flag' });
    return res;
  }

  if (offer) {
    const cand = offer.candidates.find(c => c.patientId === p.id);
    if (intent === 'confirm' || /(?<![a-z0-9])(yes|yeah|yep|sure|ok|okay|take it|book it|please|y)(?![a-z0-9])/i.test(body)) {
      res.offerId = offer.id;
      if (offer.status === 'open') {
        const booked = acceptOffer(s, offer, cand, now);
        mark('accept');
        res.apptId = booked.id;
        say('It’s yours, ' + first + '. You’re booked ' + whenLabel(offer.start, now) + ' with ' + providerOf(S, offer.provider).short + '. We’ll text a reminder before the visit.');
      } else {
        cand.reply = 'late';
        cand.replyAt = iso(now);
        mark('taken');
        say('Sorry, ' + first + ', that spot was just taken by someone who replied first. You’re still on the waitlist and we’ll text you the next opening.');
      }
      return res;
    }
    if (intent === 'decline') {
      cand.reply = 'no';
      cand.replyAt = iso(now);
      const w = s.waitlist.find(x => x.id === cand.waitId);
      if (w && w.status === 'offered') w.status = 'waiting';
      mark('decline');
      say('No problem, you’re still on the waitlist. We’ll text you when another time opens up.');
      return res;
    }
  }

  if (intent === 'late') {
    mark('late');
    if (appt) appt.late = iso(now);
    say('Thanks for letting us know, ' + first + '. I’ve told the front desk. If you’ll be more than 15 minutes late we may need to move your visit, and they’ll text you if so.');
    note(s, p.id, 'Running late: “' + body + '”', now + 100, { kind: 'late' });
    return res;
  }

  if (pend && pend.kind === 'pick') {
    const i = Number.isInteger(hint.pick) && hint.pick >= 0 && hint.pick < pend.options.length ? hint.pick : pickOption(body, pend.options);
    if (i >= 0) {
      const old = apptById(s, pend.apptId);
      const moved = bookFrom(s, old, pend.options[i], now, 'text');
      p.pending = null;
      mark('reschedule');
      res.apptId = moved.id;
      const offered = s.offers.some(o => o.apptId === pend.apptId && o.status === 'open');
      say('Done. You’re now booked ' + whenLabel(moved.start, now) + ' with ' + providerOf(S, moved.provider).short + '. ' + (pend.rebook ? 'See you then!' : offered ? 'Your old time is going to someone on our waitlist, so thank you for letting us know.' : 'Thanks for letting us know.'));
      return res;
    }
  }

  const pref = parsePref(hint.when || body, now, S);
  const wantsTime = intent === 'reschedule' || (pend && (pend.kind === 'when' || pend.kind === 'pick') && pref.has);

  if (wantsTime) {
    const target = pend && pend.apptId ? apptById(s, pend.apptId) : appt;
    if (!target) {
      say('I can’t find an upcoming visit for this number. Reply CALL and the front desk will sort it out.');
      return res;
    }
    mark('reschedule');
    if (!pref.has) {
      p.pending = { kind: 'when', apptId: target.id, rebook: pend ? !!pend.rebook : false };
      say('No problem, ' + first + '. What day and time would suit you better? For example “Thursday afternoon” or “next week, mornings”.');
      return res;
    }
    const { opts, widened } = findOptions(s, target, pref, now);
    if (!opts.length) {
      p.pending = { kind: 'when', apptId: target.id, rebook: pend ? !!pend.rebook : false };
      flag(s, p, 'callback', now, body);
      say('I couldn’t find an opening that fits. I’ve asked the front desk to call you with some options.');
      return res;
    }
    p.pending = { kind: 'pick', apptId: target.id, options: opts, rebook: pend ? !!pend.rebook : false };
    const lines = opts.map((o, i) => optionLine(s, o, i, now, target.provider));
    say((widened ? 'That’s fully booked, but here’s the closest' : 'Here’s what’s open') + ' with ' + providerOf(S, target.provider).short + ':' + NL + lines.join(NL) + NL + 'Reply ' + (opts.length === 1 ? '1' : opts.length === 2 ? '1 or 2' : '1, 2 or 3') + ' to pick one.');
    note(s, p.id, 'Offered ' + opts.length + ' open time' + (opts.length === 1 ? '' : 's') + (pref.part ? ' (' + pref.part + ')' : ''), now + 150, { kind: 'options' });
    return res;
  }

  if (pend && pend.kind === 'pick' && intent !== 'cancel' && intent !== 'question') {
    say('Just reply ' + (pend.options.length === 1 ? '1' : pend.options.length === 2 ? '1 or 2' : '1, 2 or 3') + ' to pick a time, or tell me a day that suits you better.');
    return res;
  }

  if (intent === 'cancel') {
    if (!appt) {
      say('I can’t find an upcoming visit for this number. Reply CALL and the front desk will help.');
      return res;
    }
    mark('cancel');
    const when = whenLabel(appt.start, now);
    cancelAppt(s, appt, now, 'text');
    p.pending = { kind: 'when', apptId: appt.id, rebook: true };
    say('Okay, your visit ' + when + ' is cancelled. If you’d like to book another time, just reply with a day that suits you.');
    return res;
  }

  if (intent === 'confirm') {
    if (!appt) {
      say('Thanks, ' + first + '! There’s nothing booked for this number right now. Reply CALL if you’d like the front desk to book you in.');
      return res;
    }
    mark('confirm');
    if (appt.confirmedAt) {
      say('You’re all set for ' + whenLabel(appt.start, now) + '. See you then!');
      return res;
    }
    appt.confirmedAt = iso(now);
    appt.confirmedBy = 'text';
    appt.status = 'confirmed';
    say('Thanks, ' + first + '. You’re confirmed for ' + whenLabel(appt.start, now) + ' with ' + providerOf(S, appt.provider).short + '. Reply R if anything changes.');
    note(s, p.id, 'Confirmed by text', now + 100, { kind: 'confirm', apptId: appt.id });
    return res;
  }

  if (intent === 'question') {
    mark('question');
    const ans = faq(body, S, appt);
    say((ans || 'Good question. I’ve passed it to the front desk and they’ll text you back.') + (appt && !appt.confirmedAt ? ' Reply C to confirm your visit ' + dayLabel(appt.start, now) + '.' : ''));
    if (!ans) flag(s, p, 'callback', now, body);
    return res;
  }

  if (intent === 'thanks') {
    say(appt ? 'You’re welcome! See you ' + dayLabel(appt.start, now) + '.' : 'You’re welcome!');
    return res;
  }

  mark('other');
  say('Sorry, I didn’t catch that. Reply C to confirm, R to reschedule, or CALL and the front desk will phone you.');
  return res;
}

function bookFrom(s, old, slot, now, by) {
  const S = s.settings;
  const n = {
    ...old,
    id: uid(s, 'a'),
    start: slot.start,
    provider: slot.provider,
    status: 'confirmed',
    confirmedAt: iso(now),
    confirmedBy: 'move',
    bookedAt: iso(now),
    reminders: {},
    movedFrom: old.id,
    movedTo: null,
    source: by,
    replyIntent: null,
    offerId: null,
    filledBy: null,
    late: null,
    cancelledAt: null
  };
  s.appts.push(n);
  const freed = ACTIVE.includes(old.status);
  if (freed) {
    old.status = 'moved';
    old.cancelledAt = iso(now);
  }
  old.movedTo = n.id;
  note(s, old.patientId, (freed ? 'Moved by text from ' + whenLabel(old.start, now) + ' to ' : 'Rebooked by text for ') + whenLabel(n.start, now), now + 140, { kind: 'moved', apptId: n.id });
  if (freed) backfill(s, old, now + 1200);
  return n;
}

function cancelAppt(s, appt, now, by) {
  const p = patientById(s, appt.patientId);
  appt.status = 'cancelled';
  appt.cancelledAt = iso(now);
  appt.cancelledBy = by;
  if (Date.parse(appt.start) - now < DAY && p) p.lateCancels += 1;
  note(s, appt.patientId, 'Cancelled ' + (by === 'text' ? 'by text' : 'by the front desk') + ': ' + whenLabel(appt.start, now), now + 140, { kind: 'cancelled', apptId: appt.id });
  return backfill(s, appt, now + 1200);
}

function rankWaitlist(s, freed, now) {
  const S = s.settings;
  const prov = providerOf(S, freed.provider);
  const pp = parts(freed.start);
  const h = pp.h;
  const wd = pp.wd;
  const start = Date.parse(freed.start);
  const tried = new Set();
  for (const o of s.offers) if (o.apptId === freed.id) o.candidates.forEach(c => tried.add(c.patientId));
  return s.waitlist
    .filter(w => w.status === 'waiting' && !tried.has(w.patientId))
    .map(w => {
      const t = typeOf(S, w.type);
      const p = patientById(s, w.patientId);
      if (!p || p.optedOut) return null;
      if (t.role !== prov.role || t.minutes > freed.minutes) return null;
      if (w.provider !== 'any' && w.provider !== freed.provider) return null;
      if (w.window === 'mornings' && h >= S.lunchHour) return null;
      if (w.window === 'afternoons' && h < S.lunchHour) return null;
      if (w.window === 'late' && h < 15) return null;
      if (w.days && w.days.length && !w.days.includes(wd)) return null;
      const clash = s.appts.some(a => a.patientId === p.id && ACTIVE.includes(a.status) && Math.abs(Date.parse(a.start) - start) < 3 * HOUR);
      if (clash) return null;
      const waited = Math.max(0, (now - Date.parse(w.addedAt)) / DAY);
      const reasons = [];
      let score = 40 + Math.min(30, waited * 1.2);
      reasons.push('Waiting ' + Math.max(1, Math.round(waited)) + ' day' + (Math.round(waited) === 1 ? '' : 's'));
      if (t.minutes === freed.minutes) {
        score += 8;
        reasons.push('Same length visit');
      }
      if (w.provider === freed.provider) {
        score += 6;
        reasons.push('Asked for ' + prov.short);
      }
      if (w.priority) {
        score += 14;
        reasons.push('Flagged as urgent');
      }
      if (p.noShows) {
        score -= 12 * p.noShows;
        reasons.push('Missed a visit before');
      }
      return { w, p, score: Math.round(score), reasons, value: t.value };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score)
    .filter((r, i, all) => all.findIndex(x => x.p.id === r.p.id) === i);
}

function backfill(s, freed, now, force = false) {
  const S = s.settings;
  if (!S.autoFill && !force) {
    note(s, freed.patientId, 'Time released. Auto-fill is off, so it stays open.', now, { kind: 'released', apptId: freed.id });
    return null;
  }
  if (Date.parse(freed.start) - now < S.minNoticeHours * HOUR) return null;
  if (s.offers.some(o => o.apptId === freed.id && o.status === 'open')) return null;
  const ranked = rankWaitlist(s, freed, now).slice(0, S.offerBatch);
  if (!ranked.length) {
    note(s, freed.patientId, 'Time released. Nobody on the waitlist fits it yet.', now, { kind: 'released', apptId: freed.id });
    return null;
  }
  const offer = {
    id: uid(s, 'o'),
    apptId: freed.id,
    provider: freed.provider,
    start: freed.start,
    minutes: freed.minutes,
    reason: freed.status,
    sentAt: iso(now),
    expiresAt: iso(now + S.offerMinutes * MIN),
    status: 'open',
    filledAt: null,
    winner: null,
    newApptId: null,
    value: ranked[0].value,
    candidates: ranked.map(r => ({ waitId: r.w.id, patientId: r.p.id, score: r.score, reasons: r.reasons, reply: null, replyAt: null }))
  };
  s.offers.push(offer);
  freed.offerId = offer.id;
  ranked.forEach((r, i) => {
    r.w.status = 'offered';
    r.w.offerId = offer.id;
    const vars = textVars(S, freed, r.p, now);
    addMessage(s, { patientId: r.p.id, offerId: offer.id, dir: 'out', author: 'ai', kind: 'offer', body: fill(S.templateOffer, vars), at: iso(now + 300 + i * 350) });
  });
  note(s, freed.patientId, 'Offered to ' + ranked.length + ' on the waitlist', now + 60, { kind: 'offered', apptId: freed.id, offerId: offer.id });
  return offer;
}

function acceptOffer(s, offer, cand, now) {
  const S = s.settings;
  const w = s.waitlist.find(x => x.id === cand.waitId);
  const t = typeOf(S, w.type);
  const n = {
    id: uid(s, 'a'),
    patientId: cand.patientId,
    provider: offer.provider,
    type: w.type,
    start: offer.start,
    minutes: t.minutes,
    value: t.value,
    status: 'confirmed',
    confirmedAt: iso(now),
    confirmedBy: 'offer',
    bookedAt: iso(now),
    reminders: {},
    source: 'waitlist',
    fromAppt: offer.apptId,
    replyIntent: 'accept'
  };
  s.appts.push(n);
  offer.status = 'filled';
  offer.filledAt = iso(now);
  offer.winner = cand.waitId;
  offer.newApptId = n.id;
  offer.value = t.value;
  cand.reply = 'yes';
  cand.replyAt = iso(now);
  const freed = apptById(s, offer.apptId);
  if (freed) freed.filledBy = n.id;
  w.status = 'booked';
  w.apptId = n.id;
  w.bookedAt = iso(now);
  for (const c of offer.candidates) {
    if (c.waitId === cand.waitId) continue;
    const other = s.waitlist.find(x => x.id === c.waitId);
    if (other && other.status === 'offered' && other.offerId === offer.id) other.status = 'waiting';
  }
  note(s, cand.patientId, 'Booked from the waitlist: ' + whenLabel(offer.start, now), now + 100, { kind: 'filled', apptId: n.id, offerId: offer.id });
  if (freed) note(s, freed.patientId, 'Slot refilled from the waitlist in ' + Math.max(1, Math.round((now - Date.parse(offer.sentAt)) / 1000)) + 's', now + 100, { kind: 'refilled', apptId: freed.id, offerId: offer.id });
  return n;
}

function staffMessage(s, p, body, now) {
  p.unread = false;
  return addMessage(s, { patientId: p.id, dir: 'out', author: 'staff', kind: 'staff', body, at: iso(now) });
}

function confirmByCall(s, appt, now) {
  appt.confirmedAt = iso(now);
  appt.confirmedBy = 'call';
  appt.status = 'confirmed';
  appt.calledAt = iso(now);
  appt.callOutcome = 'confirmed';
  note(s, appt.patientId, 'Confirmed on a call by the front desk', now, { kind: 'confirm', apptId: appt.id });
}

function logCall(s, appt, outcome, now) {
  appt.calledAt = iso(now);
  appt.callOutcome = outcome;
  note(s, appt.patientId, outcome === 'voicemail' ? 'Front desk left a voicemail' : 'Front desk called, no answer', now, { kind: 'call', apptId: appt.id });
}

function setOutcome(s, appt, status, now) {
  const p = patientById(s, appt.patientId);
  const was = appt.status;
  appt.status = status;
  appt.outcomeAt = iso(now);
  if (p && status === 'no_show' && was !== 'no_show') p.noShows += 1;
  if (p && status === 'completed' && was !== 'completed') p.visits += 1;
}

function tick(s, now) {
  const due = s.queue.filter(q => q.at <= now).sort((a, b) => a.at - b.at);
  if (due.length) s.queue = s.queue.filter(q => q.at > now);
  for (const q of due) {
    const p = patientById(s, q.patientId);
    if (p) inbound(s, p.phone, q.body, q.at);
  }
  for (const o of s.offers) {
    if (o.status !== 'open' || Date.parse(o.expiresAt) > now) continue;
    o.status = 'expired';
    for (const c of o.candidates) {
      const w = s.waitlist.find(x => x.id === c.waitId);
      if (w && w.status === 'offered' && w.offerId === o.id) w.status = 'waiting';
    }
    const freed = apptById(s, o.apptId);
    if (freed && !freed.filledBy) backfill(s, freed, now);
  }
}

function publicState(s, now) {
  return {
    settings: s.settings,
    patients: s.patients,
    appts: s.appts,
    waitlist: s.waitlist,
    offers: s.offers,
    messages: s.messages,
    queued: s.queue.length,
    serverNow: iso(now)
  };
}

const KINDS = { patient: 'patients', appt: 'appts', wait: 'waitlist', offer: 'offers', message: 'messages' };
const SNAP = {};

function loadState(rows) {
  const s = emptyState(DEFAULT_SETTINGS);
  for (const r of rows) {
    if (!r || !r.rid || !r.data) continue;
    SNAP[r.rid] = r.data;
    let d = null;
    try {
      d = JSON.parse(r.data);
    } catch (e) {
      continue;
    }
    if (r.kind === 'settings') s.settings = Object.assign({}, DEFAULT_SETTINGS, d);
    else if (r.kind === 'meta') {
      s.seq = d.seq || 0;
      s.queue = d.queue || [];
    } else if (KINDS[r.kind]) s[KINDS[r.kind]].push(d);
  }
  s.messages.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  setZone(s.settings.timezone);
  return s;
}

function allRows(s) {
  const out = [
    { rid: 'settings', kind: 'settings', data: JSON.stringify(s.settings) },
    { rid: 'meta', kind: 'meta', data: JSON.stringify({ seq: s.seq, queue: s.queue }) }
  ];
  for (const kind of Object.keys(KINDS)) for (const x of s[KINDS[kind]]) out.push({ rid: x.id, kind, data: JSON.stringify(x) });
  return out;
}

function changedRows(s) {
  return allRows(s).filter(r => r.rid === 'meta' || SNAP[r.rid] !== r.data);
}

function newTexts(s, before) {
  const phones = Object.fromEntries(s.patients.map(p => [p.id, p]));
  return s.messages
    .filter(m => m.dir === 'out' && !before.has(m.id) && phones[m.patientId] && !phones[m.patientId].optedOut)
    .map(m => ({ to: phones[m.patientId].phone, body: m.body }));
}

function stateRows(name) {
  return $(name || 'Load State').all().map(i => i.json);
}


const FIRST = ['Ava', 'Marcus', 'Priya', 'Diego', 'Hannah', 'Owen', 'Grace', 'Malik', 'Sofia', 'Ethan', 'Leah', 'Noah', 'Isabel', 'Caleb', 'Mei', 'Jonah', 'Rosa', 'Tyler', 'Amara', 'Lucas', 'Chloe', 'Andre', 'Nina', 'Ben', 'Fatima', 'Ryan', 'Elena', 'Jamal', 'Clara', 'Henry', 'Yusuf', 'Maya', 'Derek', 'Ines', 'Theo', 'Keisha', 'Sam', 'Lily', 'Victor', 'Zoe', 'Omar', 'Paige', 'Arjun', 'Tessa', 'Wes', 'Carmen', 'Felix', 'Dana', 'Kofi', 'Ruth'];
const LAST = ['Bell', 'Kim', 'Pratt', 'Delgado', 'Nguyen', 'Shah', 'Okoro', 'Russo', 'Fischer', 'Lopez', 'Hayes', 'Brennan', 'Moreno', 'Adler', 'Chen', 'Walsh', 'Ibrahim', 'Turner', 'Sato', 'Novak', 'Reid', 'Haddad', 'Foster', 'Silva', 'Murphy', 'Larsen', 'Grant', 'Mensah', 'Price', 'Ortiz', 'Kowalski', 'Byrne', 'Rahman', 'Doyle', 'Vargas', 'Quinn', 'Petrov', 'Hart', 'Molina', 'Ellis'];
const AREAS = ['512', '737', '210', '830', '254'];

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const CONFIRMS = ['C', 'c', 'Confirm', 'Confirmed, thanks!', 'Yes', 'C thanks', 'Yep see you then', 'c', 'Confirmed', 'Yes I’ll be there'];

function buildDemo(now, settings = DEFAULT_SETTINGS) {
  const s = emptyState(settings);
  const S = s.settings;
  const r = rng(20261006);
  const pick = arr => arr[Math.floor(r() * arr.length)];
  const between = (a, b) => a + r() * (b - a);
  const today = dayStart(now);
  const inHours = isWorkday(now) && hourOf(now) >= S.openHour && hourOf(now) < S.closeHour - 1;

  const phones = new Set([S.clinicPhone, S.frontDeskPhone]);
  const usedNames = new Set();
  const makePhone = () => {
    for (;;) {
      const p = '+1' + pick(AREAS) + '55501' + String(Math.floor(r() * 100)).padStart(2, '0');
      if (!phones.has(p)) {
        phones.add(p);
        return p;
      }
    }
  };
  const makeName = () => {
    for (;;) {
      const n = pick(FIRST) + ' ' + pick(LAST);
      if (!usedNames.has(n)) {
        usedNames.add(n);
        return n;
      }
    }
  };
  const addPatient = (name, extra = {}) => {
    const roll = r();
    const p = {
      id: uid(s, 'p'),
      name: name || makeName(),
      phone: makePhone(),
      since: iso(now - between(20, 2400) * DAY),
      visits: r() < 0.12 ? 0 : Math.floor(between(1, 16)),
      noShows: roll < 0.7 ? 0 : roll < 0.9 ? 1 : roll < 0.98 ? 2 : 3,
      lateCancels: r() < 0.82 ? 0 : 1,
      optedOut: false,
      aiPaused: false,
      flag: null,
      pending: null,
      lastReplyAt: null,
      unread: false,
      ...extra
    };
    if (name) usedNames.add(name);
    s.patients.push(p);
    return p;
  };

  const scripted = {
    marcus: addPatient('Marcus Bell', { visits: 7, noShows: 0, lateCancels: 0 }),
    rosa: addPatient('Rosa Delgado', { visits: 4, noShows: 0 }),
    priya: addPatient('Priya Shah', { visits: 2, noShows: 1 }),
    owen: addPatient('Owen Pratt', { visits: 5, noShows: 0 }),
    grace: addPatient('Grace Kim', { visits: 9, noShows: 0 }),
    diego: addPatient('Diego Moreno', { visits: 3, noShows: 1, lateCancels: 1 }),
    hannah: addPatient('Hannah Walsh', { visits: 6, noShows: 0 }),
    tyler: addPatient('Tyler Novak', { visits: 1, noShows: 2 }),
    elena: addPatient('Elena Russo', { visits: 11, noShows: 0 }),
    jamal: addPatient('Jamal Reid', { visits: 0, noShows: 0 })
  };
  for (let i = 0; i < 150; i++) addPatient();
  const pool = s.patients.filter(p => !Object.values(scripted).includes(p));

  const addAppt = (patient, provider, type, start, extra = {}) => {
    const t = typeOf(S, type);
    const a = {
      id: uid(s, 'a'),
      patientId: patient.id,
      provider,
      type,
      start: iso(start),
      minutes: t.minutes,
      value: t.value,
      status: 'booked',
      bookedAt: iso(start - between(3, 45) * DAY),
      reminders: {},
      confirmedAt: null,
      confirmedBy: null,
      source: r() < 0.7 ? 'phone' : 'online',
      replyIntent: null,
      ...extra
    };
    if (Date.parse(a.bookedAt) > now) a.bookedAt = iso(now - between(1, 40) * HOUR);
    s.appts.push(a);
    return a;
  };

  const waitAdd = (patient, type, extra = {}) => {
    const w = { id: uid(s, 'w'), patientId: patient.id, type, provider: 'any', window: 'any', days: null, addedAt: iso(now - between(1, 26) * DAY), status: 'waiting', priority: false, note: '', offerId: null, apptId: null, ...extra };
    s.waitlist.push(w);
    return w;
  };

  const tomorrow = nextWorkday(now, 1);
  const dayAfter = nextWorkday(now, 2);
  const res = {
    marcus: addAppt(scripted.marcus, 'reyes', 'cleaning', atTime(tomorrow, 9), { bookedAt: iso(now - 41 * DAY) }),
    rosa: addAppt(scripted.rosa, 'patel', 'filling', atTime(tomorrow, 14), { bookedAt: iso(now - 9 * DAY) }),
    priya: addAppt(scripted.priya, 'okafor', 'crown', atTime(tomorrow, 10), { bookedAt: iso(now - 23 * DAY) }),
    diego: addAppt(scripted.diego, 'reyes', 'cleaning', atTime(dayAfter, 15), { bookedAt: iso(now - 52 * DAY) }),
    tyler: addAppt(scripted.tyler, 'okafor', 'filling', atTime(tomorrow, 8), { bookedAt: iso(now - 33 * DAY) }),
    jamal: addAppt(scripted.jamal, 'patel', 'exam', atTime(tomorrow, 11), { bookedAt: iso(now - 30 * DAY) }),
    hannah: addAppt(scripted.hannah, 'patel', 'whitening', atTime(dayAfter, 9), { bookedAt: iso(now - 15 * DAY) })
  };

  const WEIGHTS = [['exam', 16], ['filling', 30], ['crown', 12], ['rootcanal', 7], ['whitening', 9], ['emergency', 6]];
  const total = WEIGHTS.reduce((a, b) => a + b[1], 0);
  const dentistType = () => {
    let x = r() * total;
    for (const [k, w] of WEIGHTS) {
      x -= w;
      if (x <= 0) return k;
    }
    return 'filling';
  };

  const keep = new Set([atTime(dayAfter, 13), atTime(dayAfter, 16)]);
  const history = [];
  for (let d = -30; d <= 13; d++) {
    const day = addDays(today, d);
    if (!isWorkday(day)) continue;
    const fillP = d <= 0 ? 0.9 : Math.max(0.34, 0.93 - 0.05 * d);
    const usedToday = new Set(s.appts.filter(a => dayStart(Date.parse(a.start)) === day).map(a => a.patientId));
    const who = () => {
      for (let k = 0; k < 50; k++) {
        const p = pick(pool);
        if (!usedToday.has(p.id)) {
          usedToday.add(p.id);
          return p;
        }
      }
      return pick(pool);
    };
    for (const p of S.providers) {
      let h = S.openHour;
      while (h < S.closeHour) {
        if (h >= S.lunchHour && h < S.lunchHour + 1) {
          h = S.lunchHour + 1;
          continue;
        }
        const type = p.role === 'hygienist' ? 'cleaning' : dentistType();
        const t = typeOf(S, type);
        const start = atTime(day, Math.floor(h), h % 1 ? 30 : 0);
        if (p.role === 'hygienist' && keep.has(start)) {
          h += 1;
          continue;
        }
        if (r() < fillP && fitsHours(S, start, t.minutes) && !busy(s.appts, p.key, start, t.minutes)) {
          if (type === 'emergency' && d > 2) {
            h += 0.5;
            continue;
          }
          const lead = type === 'emergency' ? between(0.1, 1.5) : r() < 0.4 ? between(2, 13) : r() < 0.6 ? between(14, 35) : between(36, 90);
          history.push(addAppt(who(), p.key, type, start, { bookedAt: iso(Math.min(start - lead * DAY, now - between(1, 30) * HOUR)) }));
          h += t.minutes / 60;
        } else {
          h += p.role === 'hygienist' ? 1 : r() < 0.5 ? 0.5 : 1;
        }
      }
    }
  }

  const refill = (freed, at) => {
    const freedP = patientById(s, freed.patientId);
    const role = S.providers.find(x => x.key === freed.provider).role;
    const types = S.types.filter(t => t.role === role && t.minutes <= freed.minutes && t.key !== 'emergency');
    if (!types.length) return null;
    const t = pick(types);
    const winner = pick(pool.filter(p => p !== freedP));
    const sentAt = at + 60000;
    const filledAt = sentAt + between(40, 900) * 1000;
    const w = { id: uid(s, 'w'), patientId: winner.id, type: t.key, provider: 'any', window: 'any', days: null, addedAt: iso(at - between(2, 30) * DAY), status: 'booked', priority: false, note: '', offerId: null, apptId: null, bookedAt: iso(filledAt) };
    s.waitlist.push(w);
    const n = {
      id: uid(s, 'a'), patientId: winner.id, provider: freed.provider, type: t.key, start: freed.start, minutes: t.minutes, value: t.value,
      status: 'booked', bookedAt: iso(filledAt), reminders: {}, confirmedAt: iso(filledAt), confirmedBy: 'offer', source: 'waitlist', fromAppt: freed.id, replyIntent: 'accept'
    };
    if (Date.parse(n.start) + n.minutes * MIN <= now) {
      n.status = r() < 0.97 ? 'completed' : 'no_show';
      n.outcomeAt = iso(Date.parse(n.start) + n.minutes * MIN);
    } else if (Date.parse(n.start) <= now) n.status = 'arrived';
    else n.status = 'confirmed';
    s.appts.push(n);
    w.apptId = n.id;
    const others = [pick(pool), pick(pool)].filter(p => p !== winner && p !== freedP);
    const cands = [{ waitId: w.id, patientId: winner.id, score: Math.round(between(62, 88)), reasons: [], reply: 'yes', replyAt: iso(filledAt) }]
      .concat(others.map((p, i) => ({ waitId: null, patientId: p.id, score: Math.round(between(44, 61)), reasons: [], reply: i === 0 && r() < 0.5 ? 'late' : null, replyAt: i === 0 ? iso(filledAt + between(30, 400) * 1000) : null })));
    const offer = { id: uid(s, 'o'), apptId: freed.id, provider: freed.provider, start: freed.start, minutes: freed.minutes, reason: freed.status, sentAt: iso(sentAt), expiresAt: iso(sentAt + S.offerMinutes * MIN), status: 'filled', filledAt: iso(filledAt), winner: w.id, newApptId: n.id, value: t.value, candidates: cands };
    w.offerId = offer.id;
    s.offers.push(offer);
    freed.offerId = offer.id;
    freed.filledBy = n.id;
    return n;
  };

  const later = [];
  for (const a of history) {
    const p = patientById(s, a.patientId);
    const start = Date.parse(a.start);
    const booked = Date.parse(a.bookedAt);
    const r0 = riskOf(a, p, start - DAY, S).score;
    const first = start - S.reminderFirst * HOUR;
    const second = start - S.reminderSecond * HOUR;
    if (first > booked && first <= now) a.reminders.first = iso(first);
    if (second > booked && second <= now) a.reminders.second = iso(second);
    const reminded = a.reminders.second || a.reminders.first;
    const roll = r();
    const remindAt = Date.parse(reminded || a.bookedAt);
    if (reminded && roll < 0.045 && start - now > -30 * DAY) {
      const at = Math.min(now - 5 * MIN, remindAt + between(0.2, 20) * HOUR);
      if (at < start - 2 * HOUR) {
        a.status = 'cancelled';
        a.cancelledAt = iso(at);
        a.cancelledBy = 'text';
        a.replyIntent = 'cancel';
        if (r() < 0.78) later.push(() => refill(a, at));
        continue;
      }
    }
    if (reminded && roll >= 0.045 && roll < 0.11) {
      const at = Math.min(now - 5 * MIN, remindAt + between(0.2, 12) * HOUR);
      if (at < start - 2 * HOUR) {
        const slots = openSlots(s, { minutes: a.minutes, providers: [a.provider], days: [nextWorkday(start, 1 + Math.floor(r() * 4))], now: at, limit: 2 });
        if (slots.length) {
          const n = { ...a, id: uid(s, 'a'), start: slots[0].start, status: 'confirmed', confirmedAt: iso(at), confirmedBy: 'move', bookedAt: iso(at), reminders: {}, movedFrom: a.id, source: 'text', replyIntent: null };
          s.appts.push(n);
          a.status = 'moved';
          a.cancelledAt = iso(at);
          a.movedTo = n.id;
          a.replyIntent = 'reschedule';
          if (Date.parse(n.start) < now) n.status = r() < 0.97 ? 'completed' : 'no_show';
          if (r() < 0.72) later.push(() => refill(a, at));
          continue;
        }
      }
    }
    if (reminded) {
      const pConfirm = Math.max(0.35, 0.93 - r0 / 220);
      if (r() < pConfirm) {
        const at = remindAt + between(2, 300) * MIN;
        if (at <= now) {
          a.confirmedAt = iso(at);
          a.confirmedBy = 'text';
          a.status = 'confirmed';
          const q = r();
          a.replyIntent = q < 0.04 ? 'question' : q < 0.06 ? 'late' : 'confirm';
        }
      } else if (r0 >= 45 && second <= now && r() < 0.55) {
        const at = second + between(3, 6) * HOUR;
        if (at <= now && at < start) {
          a.calledAt = iso(at);
          if (r() < 0.6) {
            a.confirmedAt = iso(at);
            a.confirmedBy = 'call';
            a.status = 'confirmed';
            a.callOutcome = 'confirmed';
          } else a.callOutcome = r() < 0.5 ? 'voicemail' : 'no_answer';
        }
      }
    }
    if (start + a.minutes * MIN <= now) {
      const pNo = a.confirmedAt ? 0.022 : 0.14 + r0 / 300;
      a.outcomeAt = iso(start + a.minutes * MIN);
      if (r() < pNo) {
        a.status = 'no_show';
        p.noShows += 1;
      } else {
        a.status = 'completed';
        p.visits += 1;
      }
    } else if (start <= now) {
      a.status = 'arrived';
    }
  }
  later.forEach(f => f());

  const types = ['cleaning', 'cleaning', 'cleaning', 'cleaning', 'cleaning', 'cleaning', 'filling', 'filling', 'filling', 'crown', 'exam', 'exam', 'whitening', 'rootcanal'];
  const windows = ['any', 'any', 'any', 'mornings', 'afternoons', 'late', 'any'];
  waitAdd(scripted.grace, 'cleaning', { addedAt: iso(now - 29 * DAY), note: 'Happy with any time, works from home' });
  waitAdd(scripted.owen, 'cleaning', { addedAt: iso(now - 27 * DAY), window: 'any' });
  waitAdd(scripted.elena, 'cleaning', { addedAt: iso(now - 8 * DAY), window: 'mornings' });
  const waitPool = pool.filter(p => !s.waitlist.some(w => w.patientId === p.id) && p.noShows < 2);
  for (let i = 0; i < 24; i++) {
    const p = waitPool[(i * 7 + 3) % waitPool.length];
    if (s.waitlist.some(w => w.patientId === p.id)) continue;
    const t = i >= 13 ? 'cleaning' : types[i % types.length];
    const prov = t === 'cleaning' ? 'any' : r() < 0.4 ? pick(['patel', 'okafor']) : 'any';
    waitAdd(p, t, { window: i >= 13 ? 'any' : pick(windows), provider: prov, days: r() < 0.2 ? [2, 4] : null, priority: t === 'crown' && i % 2 === 0, note: t === 'crown' ? 'Temporary crown, wants it done soon' : '' });
  }

  const recent = s.appts.filter(a => {
    const t = Date.parse(a.start);
    return t >= addDays(today, -2) && t < addDays(today, 4) && !Object.values(res).includes(a);
  });
  for (const a of recent) {
    const p = patientById(s, a.patientId);
    for (const kind of ['first', 'second']) {
      if (!a.reminders[kind]) continue;
      const tpl = kind === 'first' ? S.templateFirst : S.templateSecond;
      const at = Date.parse(a.reminders[kind]);
      const vars = { first: p.name.split(' ')[0], clinic: S.shortName, when: whenAt(a.start, at), time: timeOnly(a.start), provider: S.providers.find(x => x.key === a.provider).short, address: S.address };
      addMessage(s, { patientId: p.id, apptId: a.id, dir: 'out', author: 'ai', kind: 'reminder', body: tpl.replace(/[{]([a-zA-Z0-9_]+)[}]/g, (m, k) => vars[k] || m), at: iso(at) });
    }
    if (a.confirmedAt && a.confirmedBy === 'text') {
      const at = Date.parse(a.confirmedAt);
      addMessage(s, { patientId: p.id, apptId: a.id, dir: 'in', author: 'patient', body: pick(CONFIRMS), at: iso(at), intent: 'confirm' });
      addMessage(s, { patientId: p.id, apptId: a.id, dir: 'out', author: 'ai', kind: 'reply', body: 'Thanks, ' + p.name.split(' ')[0] + '. You’re confirmed for ' + whenAt(a.start, at) + ' with ' + S.providers.find(x => x.key === a.provider).short + '. Reply R if anything changes.', at: iso(at + 2400) });
      p.lastReplyAt = iso(at);
    }
    if (a.confirmedBy === 'call') note(s, p.id, 'Confirmed on a call by the front desk', Date.parse(a.calledAt), { kind: 'confirm', apptId: a.id });
    else if (a.callOutcome) note(s, p.id, a.callOutcome === 'voicemail' ? 'Front desk left a voicemail' : 'Front desk called, no answer', Date.parse(a.calledAt), { kind: 'call', apptId: a.id });
  }

  const remind = (a, at) => sendReminder(s, a, 'second', at);
  const ago = m => now - m * MIN;

  sendReminder(s, res.diego, 'first', ago(20 * 60));
  inbound(s, scripted.diego.phone, 'Need to cancel, something came up at work. Sorry!', ago(7 * 60));
  const dOffer = s.offers.find(o => o.apptId === res.diego.id);
  if (dOffer) inbound(s, patientById(s, dOffer.candidates[dOffer.candidates.length - 1].patientId).phone, 'Yes!', ago(7 * 60 - 3));

  let askDay = dayAfter;
  for (let i = 1; i <= 5; i++) {
    const d = nextWorkday(tomorrow, i);
    if (openSlots(s, { minutes: 60, providers: ['reyes'], days: [d], from: 13, to: 17, now, limit: 3 }).length >= 2) {
      askDay = d;
      break;
    }
  }
  remind(res.marcus, ago(260));
  inbound(s, scripted.marcus.phone, 'Can’t make it then, sorry. Anything on ' + weekdayName(askDay) + ' afternoon?', ago(170));
  inbound(s, scripted.marcus.phone, '2 works', ago(166));
  inbound(s, scripted.grace.phone, 'Yes please!', ago(164));
  inbound(s, scripted.owen.phone, 'yes', ago(161));

  remind(res.rosa, ago(300));
  inbound(s, scripted.rosa.phone, 'C', ago(280));
  inbound(s, scripted.rosa.phone, 'Also my tooth from the last filling is still throbbing at night. Is that normal?', ago(18));

  remind(res.priya, ago(240));
  inbound(s, scripted.priya.phone, 'Do you take Cigna? And is there parking?', ago(95));
  inbound(s, scripted.priya.phone, 'C', ago(92));

  remind(res.jamal, ago(250));
  inbound(s, scripted.jamal.phone, 'Can someone call me about my bill? I got charged twice.', ago(52));

  remind(res.tyler, ago(310));
  const hd = s.appts.find(a => a.id === res.hannah.id);
  sendReminder(s, hd, 'first', ago(26 * 60));
  inbound(s, scripted.hannah.phone, 'Confirmed, thank you!', ago(25 * 60));

  const optOut = pool[11];
  addMessage(s, { patientId: optOut.id, dir: 'in', author: 'patient', body: 'STOP', at: iso(ago(2 * 24 * 60)), intent: 'stop' });
  addMessage(s, { patientId: optOut.id, dir: 'out', author: 'ai', kind: 'reply', body: 'You’re unsubscribed from ' + S.shortName + ' texts. Reply START to opt back in.', at: iso(ago(2 * 24 * 60 - 0.05)) });
  optOut.optedOut = true;

  if (inHours) {
    const soon = s.appts.find(a => a.status === 'confirmed' && Date.parse(a.start) > now + 8 * MIN && Date.parse(a.start) < now + 70 * MIN);
    if (soon) {
      const p = patientById(s, soon.patientId);
      sendReminder(s, soon, 'final', Date.parse(soon.start) - 2 * HOUR);
      inbound(s, p.phone, 'Running about 10 min late, stuck in traffic. Sorry!', ago(6));
    }
  }

  const live = s.appts
    .filter(a => a.status === 'booked' && !Object.values(res).includes(a) && S.providers.find(x => x.key === a.provider).role === 'hygienist' && Date.parse(a.start) > now + 4 * HOUR && Date.parse(a.start) < now + 4 * DAY)
    .sort((a, b) => Date.parse(a.start) - Date.parse(b.start))[0];
  if (live) {
    const lp = patientById(s, live.patientId);
    note(s, lp.id, 'Called the front desk to cancel', ago(4));
    const offer = cancelAppt(s, live, ago(4), 'desk');
    if (offer && offer.candidates[1]) s.queue.push({ at: now + 50000, patientId: offer.candidates[1].patientId, body: 'Yes I’ll take it' });
  }

  tick(s, now);
  for (const p of s.patients) p.unread = false;
  scripted.rosa.unread = true;
  scripted.jamal.unread = true;
  s.messages.sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
  return s;
}

function whenAt(start, at) {
  const d = dayStart(Date.parse(start));
  const t = dayStart(at);
  const time = timeOnly(start);
  const wd = new Date(start).toLocaleDateString('en-US', zoned({ weekday: 'short', month: 'short', day: 'numeric' }));
  if (d === t) return 'today, ' + wd + ' at ' + time;
  if (d === addDays(t, 1)) return 'tomorrow, ' + wd + ' at ' + time;
  return wd + ' at ' + time;
}

function timeOnly(t) {
  return new Date(t).toLocaleTimeString('en-US', zoned({ hour: 'numeric', minute: '2-digit' }));
}

function weekdayName(t) {
  return new Date(t).toLocaleDateString('en-US', zoned({ weekday: 'long' }));
}

const SCENARIOS = [
  { key: 'confirm', label: 'Confirms', name: 'Sam Carter', blurb: 'Gets the reminder and confirms with one letter.', lines: ['C'] },
  { key: 'reschedule', label: 'Reschedules', name: 'Jordan Lee', blurb: 'Can’t make it, asks for another day in plain words.', lines: ['Can’t make it then, sorry. Anything {day} afternoon?', '2 works'] },
  { key: 'waitlist', label: 'Takes a cancelled spot', name: 'Taylor Brooks', blurb: 'Is on the waitlist when someone else cancels.', lines: ['YES'] },
  { key: 'question', label: 'Asks a question', name: 'Alex Rivera', blurb: 'Asks about parking and insurance, then confirms.', lines: ['Is there parking? And do you take Delta Dental?', 'C'] },
  { key: 'clinical', label: 'Has a concern', name: 'Chris Morgan', blurb: 'Describes a symptom. The AI stays out of medicine.', lines: ['My jaw has been swollen since last night and it really hurts. Is that normal?', 'Ok, thank you'] },
  { key: 'own', label: 'Type my own', name: 'Robin Avery', blurb: 'Reply however you like.', manual: true }
];

const freshPhone = s => {
  const used = new Set(s.patients.map(p => p.phone));
  for (let i = 0; i < 100; i++) {
    const cand = '+1737555' + '01' + String(i).padStart(2, '0');
    if (!used.has(cand)) return cand;
  }
  return '+1737555' + String(1000 + Math.floor(Math.random() * 8999));
};

const weekday = t => new Date(t).toLocaleDateString('en-US', zoned({ weekday: 'long' }));

function queueReplies(s, offer, now, lines) {
  offer.candidates.forEach((c, i) => {
    const p = patientById(s, c.patientId);
    if (!p || p.demo || !lines[i]) return;
    s.queue.push({ at: now + lines[i][0], patientId: c.patientId, body: lines[i][1] });
  });
}

function startScenario(s, key, now) {
  const sc = SCENARIOS.find(x => x.key === key) || SCENARIOS[0];
  const S = s.settings;
  const you = newPatient(s, freshPhone(s), now, sc.name);
  you.demo = true;
  you.visits = 3;
  you.noShows = key === 'waitlist' ? 0 : 1;
  you.since = iso(now - 400 * DAY);

  if (key === 'waitlist') {
    const w = { id: uid(s, 'w'), patientId: you.id, type: 'cleaning', provider: 'any', window: 'any', days: null, addedAt: iso(now - 34 * DAY), status: 'waiting', priority: true, note: 'Asked for the first opening', offerId: null, apptId: null };
    s.waitlist.push(w);
    const victim = s.appts
      .filter(a => (a.status === 'booked' || a.status === 'confirmed') && a.provider === 'reyes' && !patientById(s, a.patientId).demo && Date.parse(a.start) > now + 3 * HOUR)
      .sort((a, b) => Date.parse(a.start) - Date.parse(b.start))[0];
    if (!victim) throw new Error('No appointment to cancel. Reset the demo data and try again.');
    const vp = patientById(s, victim.patientId);
    inbound(s, vp.phone, 'So sorry, I need to cancel my appointment. Something came up.', now);
    const offer = s.offers.find(o => o.apptId === victim.id && o.status === 'open');
    if (offer) {
      const lines = [[27000, 'Yes please!'], [33000, 'yes']];
      offer.candidates.filter(c => c.patientId !== you.id).forEach((c, i) => {
        if (lines[i]) s.queue.push({ at: now + lines[i][0], patientId: c.patientId, body: lines[i][1] });
      });
    }
    return { patientId: you.id, phone: you.phone, freedId: victim.id, lines: sc.lines || [] };
  }

  const days = [nextWorkday(now, 1), nextWorkday(now, 2), nextWorkday(now, 3), nextWorkday(now, 4)];
  let slot = null;
  for (const d of days) {
    slot = openSlots(s, { minutes: 60, providers: ['reyes'], days: [d], now, limit: 1 })[0];
    if (slot) break;
  }
  if (!slot) slot = { provider: 'reyes', start: iso(atTime(days[0], 12)) };
  const t = typeOf(S, 'cleaning');
  const appt = {
    id: uid(s, 'a'), patientId: you.id, provider: slot.provider, type: 'cleaning', start: slot.start, minutes: t.minutes, value: t.value,
    status: 'booked', bookedAt: iso(now - 38 * DAY), reminders: {}, confirmedAt: null, confirmedBy: null, source: 'phone', replyIntent: null
  };
  s.appts.push(appt);
  sendReminder(s, appt, 'second', now + 1400);

  let lines = sc.lines || [];
  if (key === 'reschedule') {
    const after = Date.parse(slot.start);
    let target = nextWorkday(after, 1);
    for (let i = 1; i <= 8; i++) {
      const d = nextWorkday(after, i);
      const open = openSlots(s, { minutes: 60, providers: ['reyes'], days: [d], from: 13, to: 17, now, limit: 3 });
      if (open.length >= 2) {
        target = d;
        break;
      }
    }
    lines = lines.map(l => l.replace('{day}', weekday(target)));
  }
  return { patientId: you.id, phone: you.phone, apptId: appt.id, lines };
}


function opReminders(s, now) {
  const S = s.settings;
  const h = hourOf(now);
  const quiet = h >= S.quietStart || h < S.quietEnd;
  const sent = { first: 0, second: 0, final: 0 };
  if (!quiet) {
    for (const a of s.appts) {
      if (!ACTIVE.includes(a.status)) continue;
      const start = Date.parse(a.start);
      const left = (start - now) / HOUR;
      if (left <= 0) continue;
      const lead = (start - Date.parse(a.bookedAt)) / HOUR;
      const r = a.reminders || {};
      let kind = null;
      if (left <= S.reminderFinal) kind = !r.final && lead > S.reminderFinal ? 'final' : null;
      else if (left <= S.reminderSecond) kind = !r.second && !a.confirmedAt && lead > S.reminderSecond ? 'second' : null;
      else if (left <= S.reminderFirst) kind = !r.first && !a.confirmedAt && lead > S.reminderFirst ? 'first' : null;
      if (kind && sendReminder(s, a, kind, now)) sent[kind] += 1;
    }
  }
  return { quiet, sent };
}

function opOffers(s, now) {
  const open = s.offers.filter(o => o.status === 'open').length;
  tick(s, now);
  return { open, nowOpen: s.offers.filter(o => o.status === 'open').length };
}

function opPrepare(s, now, P) {
  const S = s.settings;
  const p = s.patients.find(x => x.phone === P.phone) || null;
  const local = classify(P.text);
  const ruled = ['stop', 'start', 'clinical', 'callback'].includes(local);
  const useAi = !!(S.aiEnabled && p && !p.aiPaused && !ruled && P.text);
  const nl = String.fromCharCode(10);
  const context = [];
  if (p) {
    const appt = nextAppt(s, p, now);
    context.push('Right now it is ' + whenLabel(now, now).replace(/^today, /, '') + ' at the clinic.');
    if (appt) context.push('Their next visit: ' + whenLabel(appt.start, now) + ' with ' + providerOf(S, appt.provider).short + (appt.confirmedAt ? ', already confirmed.' : ', not confirmed yet.'));
    else context.push('They have no upcoming visit.');
    if (p.pending && p.pending.kind === 'pick') context.push('We offered these times and asked them to reply with a number: ' + p.pending.options.map((o, i) => (i + 1) + ') ' + whenLabel(o.start, now)).join('; ') + '.');
    if (p.pending && p.pending.kind === 'when') context.push('We asked them which day and time would suit them better.');
    const offer = s.offers.find(o => o.status === 'open' && o.candidates.some(c => c.patientId === p.id && !c.reply));
    if (offer) context.push('We offered them an open spot from the waitlist: ' + whenLabel(offer.start, now) + '. A yes means they want it.');
    const last = s.messages.filter(m => m.patientId === p.id && m.dir !== 'note').slice(-6);
    if (last.length) context.push('Recent texts:' + nl + last.map(m => (m.dir === 'in' ? 'Patient: ' : 'Clinic: ') + m.body).join(nl));
  }
  const system = [
    'You read text messages that patients send to ' + S.clinicName + ', a dental clinic, in reply to appointment reminders and waitlist offers.',
    'Work out what the patient wants. Answer with JSON only, no other text, in this shape:',
    '{"intent": "...", "when": "...", "pick": null}',
    'intent is one of: confirm, reschedule, cancel, question, clinical, late, callback, thanks, decline, other.',
    'confirm means they will come, or they say yes to an offered spot. reschedule means they want a different day or time, even if they say they cannot make it. cancel means they do not want the visit at all.',
    'clinical means they mention pain, swelling, bleeding, a symptom, medicine, or ask anything medical. Always choose clinical when in doubt. Never give advice.',
    'when is their preferred day and time rewritten in plain words using weekday names, today, tomorrow, next week, morning, afternoon, after 3 or before 11. Use an empty string when they gave none.',
    'pick is 1, 2 or 3 when they chose one of the numbered times we offered, otherwise null.'
  ].join(nl);
  return {
    useAi,
    model: S.claudeModel || 'claude-opus-5',
    system_prompt: system,
    user_prompt: context.join(nl) + nl + nl + 'New text from the patient:' + nl + P.text
  };
}

function opHandle(s, now, P) {
  const hint = {};
  if (P.ai) {
    let raw = '';
    if (Array.isArray(P.ai)) raw = P.ai.filter(c => c && c.type === 'text').map(c => c.text).join('');
    else if (typeof P.ai === 'string') raw = P.ai;
    try {
      const parsed = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
      const ok = ['confirm', 'reschedule', 'cancel', 'question', 'clinical', 'late', 'callback', 'thanks', 'decline', 'other'];
      if (ok.includes(parsed.intent)) hint.intent = parsed.intent;
      if (typeof parsed.when === 'string' && parsed.when.trim()) hint.when = parsed.when.trim();
      if (Number.isInteger(parsed.pick)) hint.pick = parsed.pick - 1;
    } catch (e) {
      hint.intent = null;
    }
  }
  const flagsBefore = Object.fromEntries(s.patients.map(p => [p.id, p.flag ? p.flag.at : null]));
  const res = inbound(s, P.phone, String(P.text || '').slice(0, 480), now, [1500, 1500], hint);
  const p = res.patient;
  const alerts = [];
  if (p.flag && !p.flag.ack && p.flag.at !== flagsBefore[p.id]) {
    const label = p.flag.kind === 'clinical' ? 'flagged a health concern' : p.flag.kind === 'callback' ? 'asked for a call back' : 'needs a reply';
    alerts.push('No-Show Shield: ' + (p.name || p.phone) + ' (' + phoneLabel(p.phone) + ') ' + label + ': ' + p.flag.text);
  }
  return { result: { intent: res.intent, readBy: hint.intent ? 'claude' : 'rules' }, alerts };
}

function opCallList(s, now) {
  const S = s.settings;
  const end = nextWorkday(now, 2) + DAY;
  const people = Object.fromEntries(s.patients.map(p => [p.id, p]));
  const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const list = s.appts
    .filter(a => ACTIVE.includes(a.status) && !a.confirmedAt && Date.parse(a.start) > now && Date.parse(a.start) < end)
    .map(a => ({ a, p: people[a.patientId], risk: riskOf(a, people[a.patientId], now, S) }))
    .filter(x => x.p && !x.p.optedOut && x.risk.score >= S.riskCallList)
    .sort((x, y) => y.risk.score - x.risk.score);
  const flags = s.patients.filter(p => p.flag && !p.flag.ack);
  const yesterday = dayStart(addDays(now, -1));
  const prev = s.appts.filter(a => dayStart(Date.parse(a.start)) === yesterday);
  const kept = prev.filter(a => a.status === 'completed').length;
  const missed = prev.filter(a => a.status === 'no_show').length;
  const filled = s.offers.filter(o => o.status === 'filled' && now - Date.parse(o.filledAt) < DAY).length;
  const cell = 'padding:10px 12px;border-bottom:1px solid #e3ece9;font-size:14px;vertical-align:top;';
  const rows = list.map(x => '<tr>' +
    '<td style="' + cell + 'white-space:nowrap;"><b>' + esc(whenLabel(x.a.start, now)) + '</b></td>' +
    '<td style="' + cell + '">' + esc(x.p.name) + '<br><span style="color:#7d9592;">' + esc(phoneLabel(x.p.phone)) + '</span></td>' +
    '<td style="' + cell + '">' + esc(typeOf(S, x.a.type).name) + ' with ' + esc(providerOf(S, x.a.provider).short) + '</td>' +
    '<td style="' + cell + 'color:#e04848;font-weight:700;text-align:right;">' + x.risk.score + '</td>' +
    '<td style="' + cell + 'color:#41595a;">' + esc(x.risk.factors.filter(f => f.points > 0).slice(0, 3).map(f => f.label).join(', ')) + '</td>' +
    '</tr>').join('');
  const flagRows = flags.map(p => '<li style="margin:6px 0;"><b>' + esc(p.name || phoneLabel(p.phone)) + '</b> (' + esc(phoneLabel(p.phone)) + '): ' + (p.flag.kind === 'clinical' ? 'health concern' : 'asked for a call') + ', &ldquo;' + esc(p.flag.text) + '&rdquo;</li>').join('');
  const html = '<div style="font-family:Arial,Helvetica,sans-serif;color:#0b1d1c;max-width:760px;">' +
    '<h2 style="margin:0 0 4px;">Good morning, ' + esc(S.frontDeskName) + '</h2>' +
    '<p style="margin:0 0 18px;color:#41595a;">Yesterday: ' + kept + ' visits kept, ' + missed + ' no-show' + (missed === 1 ? '' : 's') + ', ' + filled + ' time' + (filled === 1 ? '' : 's') + ' refilled from the waitlist.</p>' +
    (flags.length ? '<h3 style="margin:18px 0 6px;color:#e04848;">Needs a person first</h3><ul style="padding-left:18px;margin:0;">' + flagRows + '</ul>' : '') +
    '<h3 style="margin:22px 0 8px;">Call these patients (' + list.length + ')</h3>' +
    (list.length
      ? '<table style="border-collapse:collapse;width:100%;"><tr><th align="left" style="' + cell + '">When</th><th align="left" style="' + cell + '">Patient</th><th align="left" style="' + cell + '">Visit</th><th align="right" style="' + cell + '">Risk</th><th align="left" style="' + cell + '">Why</th></tr>' + rows + '</table>'
      : '<p style="color:#41595a;">Nobody to call. Every high-risk patient for the next two clinic days has confirmed.</p>') +
    '<p style="margin-top:22px;color:#7d9592;font-size:12px;">Risk is out of 100. Patients scoring ' + S.riskCallList + ' or more who have not replied to their reminder are listed.</p>' +
    '</div>';
  return {
    to: S.frontDeskEmail,
    subject: (list.length ? list.length + ' patient' + (list.length === 1 ? '' : 's') + ' to call' : 'Nobody to call') + ' before ' + new Date(end - DAY).toLocaleDateString('en-US', zoned({ weekday: 'long' })),
    html,
    count: list.length
  };
}

const NUMBER_KEYS = ['reminderFirst', 'reminderSecond', 'reminderFinal', 'offerBatch', 'offerMinutes', 'minNoticeHours', 'riskCallList', 'quietStart', 'quietEnd', 'baselineNoShowRate'];

function opAction(s, now, q) {
  const action = String(q.action || '');
  const S = s.settings;
  const patient = q.patient ? patientById(s, q.patient) : null;
  const appt = q.appt ? apptById(s, q.appt) : null;
  const out = { ok: true };
  let forward = null;
  let rebuilt = null;
  const run = () => {
    if (q.patient && !patient) return 'That patient no longer exists';
    if (q.appt && !appt) return 'That appointment no longer exists';
    if (action === 'start') {
      Object.assign(out, startScenario(s, q.scenario, now));
      return null;
    }
    if (action === 'sms') {
      forward = { phone: String(q.phone || ''), text: String(q.body || '').slice(0, 480) };
      return null;
    }
    if (action === 'send') {
      staffMessage(s, patient, String(q.body || '').slice(0, 480), now);
      return null;
    }
    if (action === 'read') {
      patient.unread = false;
      return null;
    }
    if (action === 'pause') {
      patient.aiPaused = String(q.paused) === 'true';
      note(s, patient.id, patient.aiPaused ? 'Front desk took over the conversation' : 'Handed back to the AI', now);
      return null;
    }
    if (action === 'ack') {
      if (patient.flag) patient.flag.ack = true;
      return null;
    }
    if (action === 'remind') return sendReminder(s, appt, q.kind || 'second', now, 'staff') ? null : 'This patient has opted out of texts';
    if (action === 'confirm') {
      confirmByCall(s, appt, now);
      return null;
    }
    if (action === 'call') {
      logCall(s, appt, q.outcome === 'voicemail' ? 'voicemail' : 'no_answer', now);
      return null;
    }
    if (action === 'outcome') {
      if (!['completed', 'no_show', 'arrived'].includes(q.status)) return 'Unknown outcome';
      setOutcome(s, appt, q.status, now);
      return null;
    }
    if (action === 'cancel') {
      cancelAppt(s, appt, now, 'desk');
      return null;
    }
    if (action === 'offer') return backfill(s, appt, now, true) ? null : 'Nobody on the waitlist fits that time';
    if (action === 'waitlist-remove' || action === 'waitlist-priority') {
      const w = s.waitlist.find(x => x.id === q.wait);
      if (!w) return 'That waitlist entry no longer exists';
      if (action === 'waitlist-remove') w.status = 'removed';
      else w.priority = !w.priority;
      return null;
    }
    if (action === 'settings') {
      const next = Object.assign({}, s.settings);
      for (const k of Object.keys(q)) {
        if (k === 'action' || !(k in DEFAULT_SETTINGS)) continue;
        const v = q[k];
        if (k === 'providers' || k === 'types') next[k] = JSON.parse(v);
        else if (NUMBER_KEYS.includes(k)) next[k] = Number(v);
        else if (typeof DEFAULT_SETTINGS[k] === 'boolean') next[k] = String(v) === 'true';
        else next[k] = String(v);
      }
      s.settings = next;
      return null;
    }
    if (action === 'reset') {
      if (!S.demoMode) return 'Reset only works in demo mode';
      rebuilt = buildDemo(now, S);
      return null;
    }
    return 'Unknown action ' + action;
  };
  let error = null;
  try {
    error = run();
  } catch (e) {
    error = e.message || 'Something went wrong';
  }
  return { result: error ? { ok: false, message: error } : out, forward, rebuilt, error };
}

const call = $('Engine Called').first().json;
const op = String(call.op || '');
let P = {};
try {
  P = call.payload ? JSON.parse(call.payload) : {};
} catch (e) {
  P = {};
}
const now = Date.now();
const s = loadState(stateRows());
const before = new Set(s.messages.map(m => m.id));
let result = {};
let alerts = [];
let forward = null;
let reset = false;
let rows = null;
let texts = null;

if (op === 'reminders') result = opReminders(s, now);
else if (op === 'offers') result = opOffers(s, now);
else if (op === 'prepare') result = opPrepare(s, now, P);
else if (op === 'handle') {
  const h = opHandle(s, now, P);
  result = h.result;
  alerts = h.alerts;
} else if (op === 'call-list') result = opCallList(s, now);
else if (op === 'read') result = publicState(s, now);
else if (op === 'action') {
  const a = opAction(s, now, P);
  result = a.result;
  forward = a.forward;
  if (a.rebuilt) {
    reset = true;
    rows = allRows(a.rebuilt);
    texts = [];
  }
} else if (op === 'reset') {
  reset = true;
  rows = allRows(buildDemo(now, s.settings));
  texts = [];
  result = { ok: true };
} else result = { ok: false, message: 'Unknown operation ' + op };

const S = s.settings;
return [{ json: {
  op,
  result,
  rows: rows || changedRows(s),
  texts: texts || newTexts(s, before),
  alerts,
  forward,
  reset,
  send: !S.demoMode,
  from: S.clinicPhone,
  frontDesk: S.frontDeskPhone
} }];

const r = Object.assign({}, $('Run Engine').first().json);
delete r.rows;
return [{ json: r }];
